import { estimateWithdrawal, parsePerformanceCsv, previewPerformanceImports, simulateEvaluation, simulateEvaluationScenarios, simulateWithdrawalScenarios, summarizePerformanceTrades } from './performance-model.mjs';

const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const currency=value=>value==null||value===''||!Number.isFinite(Number(value))?'—':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(value));
const number=value=>value===Infinity?'∞':value==null||Number.isNaN(Number(value))?'—':new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(Number(value));
const percent=value=>value==null?'—':`${number(value)}%`;
const emptyProfile={startingBalance:'50000',profitTarget:'9000',dailyLossLimit:'750',dailyTarget:'1200',maxDrawdown:'4500',maxStops:'3',maxTrades:'6',riskAfter2R:'50',drawdownType:'trailing',minimumDays:'30',consistencyPct:'',dailyResetTime:'00:00',sessionTimeZone:'America/New_York',safetyBuffer:'0',splitPct:'80',minimumPayout:'0',maximumPayout:'100000',unlockDd:'2100',withdrawalAmount:'1000',maintenanceLevel:'2100',prePayoutMargin:'0',autoPayout:true,simulateRestart:false,entryConventional:true,entryDirect:true,entryAbsorption:true,managementMode:'standard',guard_apply2R:false,riskConventional:'100',riskDirect:'150',riskAbsorption:'150'};
let pendingImport=null;

export function initializePerformanceState(source={}){
  const state={datasets:[],activeDatasetId:'',activeTab:'geral',showImport:false,entryFilters:{conventional:true,direct:true,absorption:true},evaluationProfile:{...emptyProfile},withdrawalProfile:{...emptyProfile},audit:[],...(source&&typeof source==='object'?source:{})};
  for(const key of ['datasets','audit'])if(!Array.isArray(state[key]))state[key]=[];
  state.entryFilters={conventional:true,direct:true,absorption:true,...(state.entryFilters||{})};
  state.datasets=state.datasets.filter(Boolean).map(set=>({...set,trades:Array.isArray(set.trades)?set.trades:[],summaries:Array.isArray(set.summaries)?set.summaries:[],sources:Array.isArray(set.sources)?set.sources:[]}));
  state.activeTab=['geral','aprovacao','saque'].includes(state.activeTab)?state.activeTab:'geral';
  state.evaluationProfile={...emptyProfile,...(state.evaluationProfile||{})};state.withdrawalProfile={...emptyProfile,...(state.withdrawalProfile||{})};
  if(!state.datasets.some(set=>set.id===state.activeDatasetId))state.activeDatasetId=state.datasets[0]?.id||'';
  return state;
}

function activeSet(state){const set=state.datasets.find(item=>item.id===state.activeDatasetId)||null;if(!set)return null;const filters=state.entryFilters||{conventional:true,direct:true,absorption:true};if(Object.values(filters).every(Boolean))return set;const types={conventional:['conventional','convencional','market'],direct:['direct','direta'],absorption:['absorption','absorção','absorcao']};return{...set,trades:set.trades.filter(trade=>{const mode=String(trade.entryMode||'').toLowerCase();return mode&&Object.entries(filters).some(([key,active])=>active&&types[key].some(type=>mode.includes(type)));})};}
function profileTrades(trades,profile){const aliases={entryConventional:['conventional','convencional','market'],entryDirect:['direct','direta'],entryAbsorption:['absorption','absorção','absorcao']},enabled=Object.entries(aliases).filter(([key])=>profile[key]!==false).flatMap(([,values])=>values);return trades.filter(trade=>{const mode=String(trade.entryMode||'').toLowerCase();return !mode?enabled.length===Object.keys(aliases).length:enabled.some(value=>mode.includes(value));});}
function labTopbar(state,set){
  const fileCount=set?.sources?.length||set?.summaries?.length||0;
  const tradeCount=set?.trades?.length||0;
  const summaryTradeCount=(set?.summaries||[]).reduce((total,item)=>total+(Number(item.summary?.tradeCount)||0),0);
  const filters=state.entryFilters||{conventional:true,direct:true,absorption:true},nameCounts=new Map();
  for(const item of state.datasets){const key=String(item.name||'').trim().toLocaleLowerCase('pt-BR');nameCounts.set(key,(nameCounts.get(key)||0)+1);}
  const datasets=state.datasets.map(item=>{
    const key=String(item.name||'').trim().toLocaleLowerCase('pt-BR'),duplicate=nameCounts.get(key)>1;
    const imported=item.importedAt?new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(item.importedAt)):'';
    const detail=(item.sources||[])[0]||`${item.trades?.length||item.summaries?.length||0} registros`;
    return `<option value="${esc(item.id)}" ${item.id===state.activeDatasetId?'selected':''}>${esc(item.name)}${duplicate?` · ${esc(item.id.slice(-6))} · ${esc(detail)}${imported?` · ${esc(imported)}`:''}`:''}</option>`;
  }).join('');
  return `<header class="pl-lab-topbar"><nav aria-label="Abas do Performance Lab" role="tablist">${[['geral','Geral'],['aprovacao','Aprovação'],['saque','Saque']].map(([id,label])=>`<button type="button" role="tab" data-pl-tab="${id}" aria-selected="${state.activeTab===id}" aria-current="${state.activeTab===id?'page':'false'}">${label}</button>`).join('')}</nav><div class="pl-dataset-picker"><label for="pl-dataset-select">Conjunto</label><select id="pl-dataset-select" data-pl-select="dataset"><option value="">Selecione uma análise</option>${datasets}</select><button type="button" class="button danger-quiet pl-delete-set" data-pl="remove-dataset" aria-label="Excluir conjunto ativo${set?`: ${esc(set.name)}`:''}" title="Excluir conjunto selecionado" ${set?'':'disabled'}>Excluir</button></div><div class="pl-top-actions"><button type="button" class="button secondary pl-download" data-pl="export" aria-label="Exportar conjunto" title="Exportar conjunto" ${set?'':'disabled'}>↓ <span>Exportar</span></button><button type="button" class="button primary pl-import-cta" data-pl="toggle-import">＋ <span>Importar CSV</span></button></div></header><section class="pl-dataset-strip"><div><span class="pl-kicker">CONJUNTO ATIVO</span><strong>${set?`${number(fileCount)} arquivo(s) · ${tradeCount?`${number(tradeCount)} trades individuais`:summaryTradeCount?`${number(summaryTradeCount)} operações no resumo · sem sequência Grid`:'0 trades individuais'}`:'Nenhum arquivo importado'}</strong></div><div class="pl-dataset-files">${(set?.sources||[]).slice(0,5).map(name=>`<span title="${esc(name)}">${esc(name)}</span>`).join('')}${(set?.sources?.length||0)>5?`<span>+${set.sources.length-5}</span>`:''}</div><div class="pl-filter-row">${[['conventional','Convencional'],['direct','Direta'],['absorption','Absorção']].map(([id,label])=>`<label><input type="checkbox" data-pl-filter="${id}" ${filters[id]?'checked':''}> ${label}</label>`).join('')}<small>Só operações executadas entram nas métricas.</small></div></section>`;
}
function formValues(form){const values=Object.fromEntries(new FormData(form));form.querySelectorAll('input[type="checkbox"][name]').forEach(input=>{values[input.name]=input.checked;});return values;}
function statusBadge(status){const labels={passed:'META ATINGIDA',failed:'REGRA VIOLADA',in_progress:'EM ANDAMENTO',pending:'CONFIGURE AS REGRAS',unavailable:'DADOS INSUFICIENTES',estimate:'ESTIMATIVA',below_minimum:'ABAIXO DO MÍNIMO',within_limit:'DENTRO DO LIMITE',met:'ATINGIDA',not_configured:'NÃO CONFIGURADO'};const cls=['passed','met','within_limit','estimate'].includes(status)?'good':['failed','unavailable','below_minimum'].includes(status)?'bad':'neutral';return `<span class="pl-badge ${cls}">${labels[status]||esc(status)}</span>`;}
function metric(label,value,caption,positive=false){return `<article class="pl-metric"><span>${label}</span><strong class="${positive?'positive':''}">${value}</strong><small>${caption}</small></article>`;}
function table(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||''}</tbody></table></div>`;}
function panel(title,content,tag=''){return `<section class="panel pl-panel"><div class="panel-heading"><h2>${title}</h2>${tag?`<span class="panel-tag">${tag}</span>`:''}</div>${content}</section>`;}
function kpiSummary(set){const grid=set?.trades?.length?summarizePerformanceTrades(set.trades,set.sequenceReliable):null;const summary=set?.summaries?.[0]?.summary;return grid?{...grid,source:'CSV Grid'}:summary?{tradeCount:summary.tradeCount,netProfit:summary.netProfit,profitFactor:summary.profitFactor,winRate:summary.winRate, maxDrawdown:summary.drawdown,source:'Relatório agregado'}:null;}
function chart(curve){if(!curve.length)return `<div class="pl-chart-empty">A curva de equity aparece quando há operações em ordem confiável.</div>`;const values=curve.map(p=>p.equity),min=Math.min(0,...values),max=Math.max(0,...values),span=max-min||1,w=760,h=210,pad=14;const pts=values.map((v,i)=>`${pad+(curve.length===1?0:i/(curve.length-1))*(w-pad*2)},${h-pad-(v-min)/span*(h-pad*2)}`);const baseline=h-pad-(0-min)/span*(h-pad*2);return `<div class="pl-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Curva acumulada de resultado por operação"><defs><linearGradient id="pl-area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#41d6b1" stop-opacity=".28"/><stop offset="1" stop-color="#41d6b1" stop-opacity="0"/></linearGradient></defs><line x1="${pad}" x2="${w-pad}" y1="${baseline}" y2="${baseline}" stroke="#344e68" stroke-dasharray="4 5"/><polygon points="${pad},${baseline} ${pts.join(' ')} ${w-pad},${baseline}" fill="url(#pl-area)"/><polyline points="${pts.join(' ')}" fill="none" stroke="#48d5b2" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg><div class="pl-chart-labels"><span>${esc(curve[0].date)}</span><span>${esc(curve.at(-1).date)}</span></div></div>`;}
function importPanel(state){const preview=pendingImport?.preview,summarizedTrades=(preview?.summaries||[]).reduce((total,item)=>total+(Number(item.summary?.tradeCount)||0),0);return `<section class="panel pl-import"><div class="panel-heading"><div><h2>Importar relatórios NinjaTrader</h2><p class="panel-description">CSV lido neste navegador · Grid, relatório NinjaTrader e CSV HSG.</p></div><button type="button" class="button secondary" data-pl="toggle-import">${state.showImport?'Fechar':'＋ Importar CSV'}</button></div>${state.showImport?`<form data-pl-form="import" class="pl-import-form"><label>Arquivos CSV<input type="file" name="files" accept=".csv,text/csv" multiple required></label><div class="pl-import-actions"><button class="button primary" type="submit">Pré-visualizar arquivos</button><span>Grid: Profit + Date. HSG: EntryMode, Direcao, EntryPrice, Data e Hora para pareamento.</span></div><div class="form-errors" role="alert"></div></form>`:''}${preview?`<div class="pl-preview"><div><strong>Prévia pronta</strong><span>${number(preview.records.length)} trades individuais${summarizedTrades?` · ${number(summarizedTrades)} operações no resumo`:''} · ${preview.entryMatches||0} entradas associadas · ${preview.errors.length} linha(s) com erro</span></div>${preview.duplicates?`<p class="pl-alert">${preview.duplicates} possível(is) duplicata(s) detectada(s). Por padrão, trades marcados serão ignorados.</p>`:''}${preview.overlaps.length?`<p class="pl-alert">Períodos coincidentes: ${preview.overlaps.map(esc).join(' · ')}. Confira se os arquivos se sobrepõem antes de importar.</p>`:''}${preview.warnings.map(w=>`<p class="pl-note">${esc(w)}</p>`).join('')}${preview.errors.length?`<p class="pl-alert">${preview.errors.slice(0,5).map(esc).join('<br>')}</p>`:''}<label class="pl-check"><input type="checkbox" name="include-duplicates"> Incluir também as possíveis duplicatas</label><label>Nome do conjunto<input name="dataset-name" value="${esc(pendingImport.name)}" maxlength="80"></label><div class="pl-import-actions"><button class="button primary" type="button" data-pl="confirm-import">Confirmar importação</button><button class="button secondary" type="button" data-pl="cancel-import">Cancelar prévia</button></div></div>`:''}</section>`;}

function importFailureMessage(parsed,preview){
  const labels={grid:'Grid',summary:'relatório agregado',hsg:'HSG'};
  const counts={grid:0,summary:0,hsg:0,unknown:0};
  for(const file of parsed)counts[file.kind||'unknown']=(counts[file.kind||'unknown']||0)+1;
  const detected=Object.entries(counts).filter(([,count])=>count>0).map(([kind,count])=>`${count} ${labels[kind]||'não reconhecido(s)'}`).join(' · ');
  const details=parsed.filter(file=>file.errors?.length).slice(0,8).map(file=>`${file.filename}: ${file.errors[0]}`);
  if(parsed.filter(file=>file.errors?.length).length>details.length)details.push(`Mais ${parsed.filter(file=>file.errors?.length).length-details.length} arquivo(s) com erro.`);
  const guidance=counts.hsg>0
    ?'O CSV HSG contém os dados das entradas, mas não o lucro individual. Inclua ao menos um CSV Grid com Profit e Date/DateTime ou um relatório agregado do NinjaTrader.'
    :'Exporte no NinjaTrader um CSV Grid com uma operação por linha e as colunas Profit e Date/DateTime, ou selecione um relatório agregado.';
  return [`Nenhum arquivo importável foi encontrado entre ${parsed.length} arquivo(s).`,`Identificados: ${detected||'nenhum formato reconhecido'}.`,guidance,...details,...(preview.errors.filter(message=>!message.startsWith('CSV HSG reconhecido')).slice(0,2))].join('\n');
}

function strengthScore(summary){if(!summary)return 0;const pf=Math.min(100,Math.max(0,summary.profitFactor||0)*28),payoff=Math.min(100,Math.max(0,summary.payoff||0)*24),returnDd=summary.maxDrawdown?Math.min(100,Math.max(0,summary.netProfit/summary.maxDrawdown)*22):0,sample=Math.min(100,Math.sqrt(summary.tradeCount||0)*5);return Math.round(pf*.35+payoff*.25+returnDd*.25+sample*.15);}
function heatmapPanel(summary){if(!summary?.heatmap?.length)return panel('Onde o resultado nasce','<div class="pl-empty-small"><p>O mapa horário precisa de datas e horários válidos no CSV Grid.</p></div>','MAPA HORÁRIO');const max=Math.max(1,...summary.heatmap.map(cell=>Math.abs(cell.profit)));const cells=new Map(summary.heatmap.map(cell=>[`${cell.weekday}:${cell.hour}`,cell]));const rows=summary.weekdayNames.map((day,index)=>`<tr><th>${day}</th>${Array.from({length:24},(_,hour)=>{const cell=cells.get(`${index}:${hour}`),intensity=cell?Math.min(.9,.12+Math.abs(cell.profit)/max*.75):0;return `<td title="${cell?`${number(cell.trades)} trades · ${currency(cell.profit)}`:'Sem trades'}" style="--heat:${intensity};--heat-color:${cell?.profit>=0?'53,211,171':'255,89,111'}">${cell?number(cell.profit):''}</td>`;}).join('')}</tr>`).join('');return panel('Onde o resultado nasce',`<div class="pl-heat-scroll"><table class="pl-heatmap"><thead><tr><th>Dia</th>${Array.from({length:24},(_,hour)=>`<th>${String(hour).padStart(2,'0')}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`,'MAPA HORÁRIO');}
function entryAnalysisPanel(summary,trades=[]){const market=trades.filter(trade=>/market|convencional/i.test(trade.entryMode||'')&&trade.side),directions=new Map();for(const trade of market){const side=/buy|long|compra/i.test(trade.side)?'Compra':/sell|short|venda/i.test(trade.side)?'Venda':trade.side,row=directions.get(side)||{side,count:0,profit:0};row.count++;row.profit+=trade.profit;directions.set(side,row);}if(!directions.size)return panel('Entrada Market: compras x vendas','<div class="pl-empty-small"><p>Não encontrei operações identificadas como ENTRY MARKET. O CSV Grid traz o lucro, mas não identifica sozinho o tipo da ordem.</p><small>Importe junto o CSV HSG que tenha EntryMode, Direcao, EntryPrice, Data e Hora. O Lab fará o pareamento por data, horário, lado, família e preço.</small></div>','TESTE DE ENTRADA · CONVENCIONAL');const rows=[...directions.values()].map(item=>`<tr><td>${esc(item.side)}</td><td>${number(item.count)}</td><td>${currency(item.profit)}</td></tr>`).join('');return panel('Entrada Market: compras x vendas',table(['Direção','Trades ENTRY MARKET','Resultado líquido'],rows),'TESTE DE ENTRADA · CONVENCIONAL');}

function renderGeneral(set){
  if(!set)return `<div class="pl-empty"><div class="pl-empty-mark">↗</div><h2>Seu desempenho, com contexto.</h2><p>Importe um relatório do NinjaTrader para começar. O CSV Grid preserva a sequência e libera a curva de equity e as simulações.</p><button class="button primary" data-pl="toggle-import">Importar primeiro CSV</button></div>`;
  const summary=kpiSummary(set),grid=set.trades?.length? summarizePerformanceTrades(set.trades,set.sequenceReliable):null;
  if(!summary)return `<div class="pl-empty"><h2>Este conjunto não tem dados analisáveis.</h2><p>Abra Importar CSV e envie um relatório agregado ou Grid com a coluna Profit.</p></div>`;
  const dd=summary.maxDrawdown==null?'Indisponível':currency(summary.maxDrawdown),win=summary.winRate==null?'—':percent(grid?summary.winRate*100:summary.winRate);
  const ddSource=grid?(set.sequenceReliable?'Calculado na ordem do Grid':'Indisponível · sequência ambígua'):'Resumo informado pelo relatório';
  const strength=strengthScore(summary),cards=`<div class="pl-metrics">${metric('Lucro líquido',currency(summary.netProfit),`${number(summary.tradeCount)} trades`,Number(summary.netProfit)>=0)}${metric('Drawdown exato',dd,'Pico a vale · sequência Grid')}${metric('Profit factor',number(summary.profitFactor),`Payoff ${number(summary.payoff)}`)}${metric('Taxa de acerto',win,`${number(summary.wins)} ganhos · ${number(summary.losses)} perdas`)}${metric('Hunter Strength',`${strength}/100`,'PF · payoff · retorno/DD · amostra')}</div>`;
  const summaries=set.summaries?.length?panel('Relatórios agregados',table(['Período','Arquivo','Trades','Lucro líquido','Profit factor','Acerto','Drawdown informado'],set.summaries.map(item=>`<tr><td>${esc(item.summary.period||'Não identificado')}</td><td>${esc(item.filename)}</td><td>${number(item.summary.tradeCount)}</td><td>${currency(item.summary.netProfit)}</td><td>${number(item.summary.profitFactor)}</td><td>${percent(item.summary.winRate)}</td><td>${currency(item.summary.drawdown)}</td></tr>`).join('')),'Cada relatório permanece separado do Grid'):'';
  const dirs=grid?.byDirection?.length?panel('Resultado por direção',table(['Direção','Trades','Resultado líquido'],grid.byDirection.map(item=>`<tr><td>${esc(item.side)}</td><td>${number(item.trades)}</td><td>${currency(item.profit)}</td></tr>`).join(''))):'';
  const monthly=grid?.byDay?.length?(()=>{const map=new Map();for(const day of grid.byDay){const key=day.date.slice(0,7),row=map.get(key)||{count:0,profit:0};row.count+=day.trades;row.profit+=day.profit;map.set(key,row);}return panel('Evolução mensal',table(['Período','Operações','Resultado líquido'],[...map].sort((a,b)=>a[0].localeCompare(b[0])).map(([month,row])=>`<tr><td>${esc(month)}</td><td>${number(row.count)}</td><td>${currency(row.profit)}</td></tr>`).join('')));})():'';
  const strengthPanel=panel('Força do conjunto',`<div class="pl-strength"><strong>${strength}<small>/100</small></strong><div><b>${strength>=70?'Conjunto consistente':strength>=40?'Força moderada':'Amostra exige cautela'}</b><p>Pontuação indicativa baseada em profit factor, payoff, retorno/drawdown e tamanho da amostra. Não representa previsão.</p></div></div>`,'HUNTER STRENGTH');
  const periods=grid?.byDay?.length?panel('Resultado por período',table(['Dia','Trades','Resultado líquido'],grid.byDay.map(day=>`<tr><td>${esc(day.date)}</td><td>${number(day.trades)}</td><td>${currency(day.profit)}</td></tr>`).join('')),'CONSISTÊNCIA'):'';
  const directions=grid?.byDirection?.length?panel('Compras x vendas',table(['Direção','Trades','Resultado líquido'],grid.byDirection.map(item=>`<tr><td>${esc(item.side)}</td><td>${number(item.trades)}</td><td>${currency(item.profit)}</td></tr>`).join(''))):'';
  return `${cards}${grid?panel('Desenvolvimento da conta',chart(grid.equityCurve),`${set.sequenceReliable?'ordem confiável':'sequência indisponível'} · ${grid.tradeCount} operações`):''}${strengthPanel}${entryAnalysisPanel(grid||summary,set.trades||[])}${summaries}${monthly}${periods}${directions}${heatmapPanel(grid)}<div class="info-strip"><span>ⓘ</span><p>Resumo agregado não contém a sequência dos trades. Drawdown de sequência e simulações usam apenas Grid individual em ordem confiável. Resultados dependem dos arquivos importados e não garantem aprovação ou saque.</p></div>`;
}

function profileFields(profile,kind){const fields=kind==='evaluation'?[['startingBalance','Saldo inicial'],['profitTarget','Meta de lucro'],['dailyLossLimit','Limite de perda diária'],['maxDrawdown','Drawdown máximo'],['minimumDays','Dias mínimos'],['consistencyPct','Limite de consistência (%)']]:[['startingBalance','Saldo de referência'],['safetyBuffer','Buffer de segurança'],['splitPct','Seu repasse (%)'],['minimumDays','Dias mínimos'],['minimumPayout','Saque mínimo'],['maximumPayout','Saque máximo']];const numeric=fields.map(([key,label])=>`<label>${label}<input type="number" name="${key}" step="0.01" min="0" value="${esc(profile[key])}" placeholder="Configurar"></label>`).join('');const session=kind==='evaluation'?`<label>Fuso horário do CSV<input type="text" name="sessionTimeZone" value="${esc(profile.sessionTimeZone)}" placeholder="Ex.: America/New_York"></label><label>Reinício diário no horário do CSV<input type="time" name="dailyResetTime" value="${esc(profile.dailyResetTime)}"></label>`:'';return numeric+session;}
function field(key,label,value,step='0.01'){return `<label>${label}<input type="number" name="${key}" min="0" step="${step}" value="${esc(value)}" placeholder="0"></label>`;}
function accountControls(profile,kind){return `<div class="pl-account-presets"><span>CONTA</span><button type="button" data-pl-account="50000" class="${Number(profile.startingBalance)===50000?'selected':''}">50K</button><button type="button" data-pl-account="150000" class="${Number(profile.startingBalance)===150000?'selected':''}">150K</button></div><p class="pl-goal">${kind==='evaluation'?'Objetivo: alcançar a meta sem violar o DD.':'Objetivo: deslocar o DD até liberar o saque.'}</p>`;}
function entryControls(profile){const cards=[['entryConventional','Convencional','riskConventional'],['entryDirect','Direta','riskDirect'],['entryAbsorption','Absorção','riskAbsorption']];return `<div class="pl-side-section"><h3>RISCO POR TIPO DE ENTRADA <span>— MARQUE O QUE ENTRA NO TESTE</span></h3><div class="pl-entry-grid">${cards.map(([key,label,risk])=>`<label class="pl-toggle-card"><span><input type="checkbox" name="${key}" ${profile[key]?'checked':''}> ATIVO</span><strong>${label}</strong><small>Risco por trade ($/R)</small><input type="number" name="${risk}" min="0" step="1" value="${esc(profile[risk])}" aria-label="Risco ${label}"></label>`).join('')}</div><small class="pl-field-hint">O CSV atual informa o resultado em dinheiro; riscos por tipo são premissas de gestão.</small></div>`;}
function guardControls(profile,kind){const guards=[['dailyStop','Stop financeiro diário','stopDaily','750'],['dailyTarget','Meta diária','dailyTarget','1200'],['maxStops','Máximo de stops','maxStops','3'],['maxTrades','Máximo de trades','maxTrades','6'],['apply2R','Redução após 2R','riskAfter2R','50']];return `<div class="pl-side-section"><h3>TRAVAS OPERACIONAIS <span>— ATIVE E AJUSTE OS VALORES</span></h3><div class="pl-guard-grid">${guards.map(([key,label,input,value])=>{const enabled=profile[`guard_${key}`]!==false,unsupported=key==='apply2R';return `<label class="pl-guard-card"><span><input type="checkbox" name="guard_${key}" ${enabled?'checked':''}> ${enabled?'CONSIDERADO':'IGNORADO'}</span><strong>${label}</strong><b>${esc(profile[input]||value)}${key==='maxStops'?' stops':key==='maxTrades'?' trades':key==='apply2R'?'% de risco':''}</b><small>${unsupported?'Não aplicado sem R por trade; confira se a redução já está embutida no CSV.':'Limite aplicado à trajetória simulada.'}</small></label>`;}).join('')}</div><p class="pl-adjust-label">VALORES AJUSTÁVEIS — altere e simule novamente</p><div class="pl-fields">${field('stopDaily','Stop financeiro diário ($)',profile.stopDaily||'750')}${field('dailyTarget','Meta diária ($)',profile.dailyTarget||'1200')}${field('maxStops','Máximo de stops',profile.maxStops||'3','1')}${field('maxTrades','Máximo de trades',profile.maxTrades||'6','1')}${field('riskAfter2R','Risco restante após 2R (%)',profile.riskAfter2R||'50')}</div></div>`;}
function profileSidebar(profile,kind){const evalMode=kind==='evaluation';const basics=evalMode?`${field('profitTarget','Meta de APROVAÇÃO ($)',profile.profitTarget)}${field('dailyLossLimit','DD diário máximo ($)',profile.dailyLossLimit)}${field('maxDrawdown','DD máximo ($)',profile.maxDrawdown)}${field('minimumDays','Prazo de avaliação (dias)',profile.minimumDays,'1')}<label>Regra de drawdown<select name="drawdownType"><option value="trailing" ${profile.drawdownType==='trailing'?'selected':''}>Dinâmico intraday</option><option value="eod" ${profile.drawdownType==='eod'?'selected':''}>Atualização fim do dia</option></select></label>`:`${field('unlockDd','Valor para DESLOCAR DD ($)',profile.unlockDd)}${field('maxDrawdown','DD máximo ($)',profile.maxDrawdown)}${field('minimumDays','Prazo de avaliação (dias)',profile.minimumDays,'1')}<label>Regra de drawdown<select name="drawdownType"><option value="trailing" ${profile.drawdownType==='trailing'?'selected':''}>Dinâmico intraday</option><option value="eod" ${profile.drawdownType==='eod'?'selected':''}>Atualização fim do dia</option></select></label>${field('maintenanceLevel','Nível que mantém DD deslocado ($)',profile.maintenanceLevel)}${field('withdrawalAmount','Valor por saque ($)',profile.withdrawalAmount)}${field('prePayoutMargin','Margem extra antes do saque ($)',profile.prePayoutMargin)}`;return `<aside class="pl-sidebar"><form data-pl-form="${evalMode?'evaluation':'withdrawal'}"><div class="pl-sidebar-head"><span>${evalMode?'MODO APROVAÇÃO':'MODO SAQUE'}</span><h2>Parâmetros da conta</h2></div>${accountControls(profile,kind)}<div class="pl-fields">${field('startingBalance','Saldo inicial ($)',profile.startingBalance)}${basics}</div>${evalMode?`<div class="pl-side-section"><h3>MODO DE APROVAÇÃO</h3><div class="pl-mode-grid"><label><input type="radio" name="managementMode" value="standard" ${profile.managementMode!=='tomahawk'?'checked':''}><b>PADRÃO</b><small>Risco fixo</small></label><label><input type="radio" name="managementMode" value="tomahawk" ${profile.managementMode==='tomahawk'?'checked':''}><b>TOMAHAWK</b><small>Lucro financia próximo risco</small></label></div></div>`:''}${!evalMode?`<div class="pl-side-section"><h3>REGRAS DE DESLOCAMENTO E SAQUE</h3><div class="pl-fields">${field('splitPct','Repasse ao trader (%)',profile.splitPct||'80')}${field('safetyBuffer','Buffer de segurança ($)',profile.safetyBuffer||'0')}</div><label class="pl-check"><input type="checkbox" name="autoPayout" ${profile.autoPayout!==false?'checked':''}> Saques automáticos</label><label class="pl-check"><input type="checkbox" name="simulateRestart" ${profile.simulateRestart?'checked':''}> Simular reposição após quebra</label></div>`:''}${entryControls(profile)}${guardControls(profile,kind)}<div class="pl-sidebar-actions"><button class="button primary" type="submit">▶ Simular parâmetros</button><button class="button secondary" type="button" data-pl="suggest-management">⚡ Buscar melhor gestão</button></div><button type="button" class="pl-reset-profile" data-pl="reset-profile">Redefinir valores</button><p class="pl-field-hint">Valores carregados como referência visual. Ajuste às regras da sua prop firm antes de simular. Risco por tipo de entrada não se aplica enquanto o CSV não trouxer essa classificação.</p></form></aside>`;}
function scenarioCards(simulation){return (simulation?.horizons||[]).map(row=>`<article class="pl-horizon-card"><b>EM ATÉ ${row.days} DIAS</b><div><span>APROVA</span><strong class="good">${percent(row.approvalPct)}</strong></div><div><span>QUEBRA O DD</span><strong class="bad">${percent(row.violationPct)}</strong></div><div><span>NÃO CONCLUI</span><strong class="warn">${percent(row.unfinishedPct)}</strong></div><div class="pl-mini-bar"><i style="width:${Math.max(0,Math.min(100,row.approvalPct))}%"></i></div><small>Probabilidade estimada em ${simulation.runs} trajetórias reamostradas.</small></article>`).join('');}
function scenarioChart(points,caption,markers=[]){if(!points?.length)return `<div class="pl-chart-empty">${esc(caption||'Importe CSV Grid com operações em ordem para desenhar a curva.')}</div>`;const levels=markers.filter(marker=>Number.isFinite(marker.value)),events=markers.filter(marker=>Number.isFinite(marker.day)),firstPoint=points[0],lastPoint=points.at(-1),leftLabel=firstPoint.trade!==undefined?(firstPoint.trade===0?'Início':`Trade ${firstPoint.trade}`):firstPoint.day?`Dia ${firstPoint.day}`:'Início',rightLabel=lastPoint.trade!==undefined?`Trade ${lastPoint.trade}`:lastPoint.day?`Dia ${lastPoint.day}`:`Dia ${points.length}`,values=points.map(item=>item.equity),min=Math.min(...values,...levels.map(m=>m.value)),max=Math.max(...values,...levels.map(m=>m.value)),span=max-min||1,w=900,h=210,pad=48;const y=value=>h-pad-(value-min)/span*(h-pad*2),x=index=>pad+(points.length===1?0:index/(points.length-1))*(w-pad*2),coords=points.map((p,i)=>`${x(i)},${y(p.equity)}`).join(' '),grid=Array.from({length:5},(_,i)=>{const value=max-(span*i/4),yy=pad+(h-pad*2)*i/4;return `<line x1="${pad}" x2="${w-14}" y1="${yy}" y2="${yy}" stroke="#203136"/><text x="0" y="${yy+3}" fill="#718589" font-size="8">${esc(currency(value))}</text>`;}).join(''),levelLines=levels.map(m=>`<line x1="${pad}" x2="${w-14}" y1="${y(m.value)}" y2="${y(m.value)}" stroke="${m.color}" stroke-dasharray="5 5"/>`).join(''),eventMarks=events.map((m,i)=>{const same=events.slice(0,i).filter(other=>other.day===m.day).length,point=points[Math.max(0,Math.min(points.length-1,m.day-1))];return `<circle cx="${x(Math.max(0,Math.min(points.length-1,m.day-1)))}" cy="${y(point.equity)+(same%2?9:-9)}" r="4" fill="${m.color}"><title>${esc(m.label)} · dia ${m.day} · ${percent(m.probability||0)}</title></circle>`;}).join(''),legend=[['Performance simulada','#36d9ad'],...levels.map(m=>[m.label||'Nível',m.color]),...events.length?[['Evento simulado','#45cbea'],['Saque','#ffb72f'],['Conta quebrada','#ff5268']]:[]];return `<div class="pl-chart-legend">${legend.map(([label,color])=>`<span><i style="--legend:${color}"></i>${esc(label)}</span>`).join('')}</div><div class="pl-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(caption)}">${grid}${levelLines}<polyline points="${coords}" fill="none" stroke="#3dd9b3" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${eventMarks}</svg><div class="pl-chart-labels"><span>${esc(leftLabel)}</span><span>${esc(rightLabel)}</span></div></div>`;}
function renderEvaluation(set,state){const profile=state.evaluationProfile,trades=profileTrades(set?.trades||[],profile),reliable=Boolean(set?.sequenceReliable),result=trades.length?simulateEvaluation(trades,profile,reliable):{status:'unavailable',reason:'Importe um CSV Grid para simular a sequência de avaliação.'},mc=simulateEvaluationScenarios(trades,profile,reliable),summary=trades.length?summarizePerformanceTrades(trades,reliable):null,ddAvailable=Math.max(0,Number(profile.maxDrawdown||0)-(summary?.maxDrawdown||0)),summaryTradeCount=(set?.summaries||[]).reduce((total,item)=>total+(Number(item.summary?.tradeCount)||0),0);const best=mc?.horizons?.at(-1);return `<div class="pl-dashboard">${profileSidebar(profile,'evaluation')}<main class="pl-main"><section class="pl-summary-band"><div><span class="pl-kicker">RESUMO DO TESTE</span><h2>Atingir a meta de aprovação</h2><small>A meta precisa ser atingida dentro do prazo e sem violar o DD.</small></div><div><span>DD máximo</span><strong>${currency(profile.maxDrawdown)}</strong></div><div><span>Base analisada</span><strong>${trades.length?`${trades.length} trades individuais · ${summary?.byDay?.length||0} dias`:summaryTradeCount?`${number(summaryTradeCount)} operações agregadas · Grid individual necessário`:'0 trades individuais · importe CSV Grid'}</strong></div><div><span>Proteção diária</span><strong>${currency(profile.dailyLossLimit)}</strong></div></section><div class="pl-stat-row"><article><span>Chance de aprovação</span><strong class="good">${best?percent(best.approvalPct):'—'}</strong><small>Monte Carlo · ${mc?.runs||1000} cenários</small></article><article><span>Chance de violação</span><strong class="bad">${best?percent(best.violationPct):'—'}</strong><small>DD intraday e diário</small></article><article><span>DD disponível</span><strong class="warn">${currency(ddAvailable)}</strong><small>de ${currency(profile.maxDrawdown)}</small></article><article><span>DD médio simulado</span><strong class="cyan">${currency(best?.averageDrawdown)}</strong><small>pico a vale · prazo de 30 dias</small></article></div><section class="panel pl-scenario-panel"><div class="panel-heading"><div><span class="pl-kicker">PROBABILIDADE POR PRAZO</span><h2>Chance de APROVAR</h2></div><span class="pl-badge neutral">${mc?.status==='complete'?'1.000 cenários':esc(mc?.reason||'CSV Grid necessário')}</span></div>${mc?.reason?`<div class="pl-empty-small"><p>${esc(mc.reason)}</p></div>`:`<div class="pl-probability-banner"><div><b>${best?.approvalPct<25?'Probabilidade baixa':'Projeção baseada no histórico'}</b><small>${mc?.sourceDays||0} dias históricos · estimativa por reamostragem diária</small></div><div class="pl-count good">${best?.passed||0}<small>aprovam · 30 dias</small></div><div class="pl-count bad">${best?.violated||0}<small>violam o DD</small></div><div class="pl-count warn">${best?.unfinished||0}<small>não concluem</small></div></div><div class="pl-horizon-grid">${scenarioCards(mc)}</div>`}</section><section class="panel pl-scenario-panel"><div class="panel-heading"><div><span class="pl-kicker">CURVA COM GERENCIAMENTO</span><h2>Percurso da performance até a aprovação</h2></div>${statusBadge(result.status)}</div>${scenarioChart(result.equityCurve,'Importe CSV Grid com cada trade e a ordem preservada para desenhar o percurso.',[{value:Number(profile.profitTarget||0),color:'#5ad6ec',label:'Meta de aprovação'},{value:ddAvailable,color:'#ffb53f',label:'DD disponível'}])}<p class="pl-field-hint">${esc(result.assumption||result.reason||mc?.assumption||'A simulação usa as regras configuradas e os resultados diários do CSV Grid.')} Quando há sequência Grid, a curva aplica a gestão configurada; a probabilidade acima é estimada separadamente por Monte Carlo.</p></section><section class="panel pl-scenario-panel"><span class="pl-kicker">DIAGNÓSTICO DA GESTÃO</span><h2>Risco, percurso e robustez</h2><div class="pl-diagnostics"><div><span>Entradas ativas</span><b>${['entryConventional','entryDirect','entryAbsorption'].filter(k=>profile[k]).length}</b></div><div><span>Resultado histórico</span><b>${currency(summary?.netProfit)}</b></div><div><span>Faixa temporal</span><b>${mc?.horizons?.at(-1)?.durationP10!=null?`${mc.horizons.at(-1).durationP10}–${mc.horizons.at(-1).durationP90} dias (P10–P90)`:'Execute a simulação'}</b></div><div><span>Modo de risco</span><b>${profile.managementMode==='tomahawk'?'Tomahawk':'Padrão'}</b></div></div></section></main></div><div class="info-strip"><span>ⓘ</span><p>As probabilidades são estimativas Monte Carlo obtidas por reamostragem dos dias históricos. Não são garantia de aprovação; confirme as regras e os horários oficiais da prop firm.</p></div>`;}
function renderWithdrawal(set,state){const profile=state.withdrawalProfile,trades=profileTrades(set?.trades||[],profile),reliable=Boolean(set?.sequenceReliable),result=trades.length?estimateWithdrawal(trades,{...profile,sequenceReliable:reliable}):{status:'unavailable',reason:'Importe um CSV Grid para estimar cenários de saque.'},mc=simulateWithdrawalScenarios(trades,profile,reliable),summary=trades.length?summarizePerformanceTrades(trades,reliable):null;return `<div class="pl-dashboard">${profileSidebar(profile,'withdrawal')}<main class="pl-main"><section class="pl-summary-band payout"><div><span class="pl-kicker">PLANO DE SAQUE</span><h2>CONSTRUÇÃO DO DD</h2><small>Primeiro alcance o nível de deslocamento configurado.</small></div><div><span>Saldo simulado</span><strong>${currency(mc?.averageEquityCurve?.at(-1)?.equity??result.endingBalance??profile.startingBalance)}</strong></div><div><span>DD disponível</span><strong>${currency(Math.max(0,Number(profile.maxDrawdown||0)-(summary?.maxDrawdown||0)))}</strong></div><div><span>Próximo saque</span><strong>${currency(profile.withdrawalAmount)}</strong><small>${result.reason?esc(result.reason):'conforme margem e regras configuradas'}</small></div><div><span>Total projetado</span><strong>${currency(mc?.averagePayoutTotal)}</strong><small>Monte Carlo · horizonte de 30 dias</small></div></section><div class="pl-stat-row"><article><span>Chance de deslocar DD</span><strong class="good">${mc?percent(mc.payoutProbability):'—'}</strong><small>${mc?.runs||1000} trajetórias · 30 dias</small></article><article><span>Chance de violação</span><strong class="bad">${mc?percent(mc.violationProbability):'—'}</strong><small>DD intraday</small></article><article><span>DD disponível</span><strong class="warn">${currency(Math.max(0,Number(profile.maxDrawdown||0)-(summary?.maxDrawdown||0)))}</strong><small>de ${currency(profile.maxDrawdown)}</small></article><article><span>DD médio simulado</span><strong class="cyan">${currency(mc?.averageDrawdown)}</strong><small>pico a vale</small></article></div><section class="panel pl-scenario-panel"><div class="panel-heading"><div><span class="pl-kicker">CURVA COM GERENCIAMENTO</span><h2>Percurso com DD, deslocamento e saques</h2></div>${statusBadge(mc?.status||result.status)}</div>${mc?.reason?`<div class="pl-empty-small"><p>${esc(mc.reason)}</p></div>`:scenarioChart(mc?.averageEquityCurve,'Importe CSV Grid e preencha os parâmetros para estimar os saques.',[{value:Number(profile.startingBalance||0)+Number(profile.unlockDd||0),color:'#46cae9',label:'DD deslocado'},{value:Number(profile.startingBalance||0)-Number(profile.maxDrawdown||0),color:'#ffb53f',label:'DD disponível'},...(mc?.markers||[])])}<div class="pl-payout-summary"><article><span>Total sacado acumulado</span><strong>${currency(mc?.averagePayoutTotal)}</strong></article><article><span>Quantidade média de saques</span><strong>${number(mc?.averagePayoutCount)}</strong></article><article><span>Valor por saque</span><strong>${currency(profile.withdrawalAmount)}</strong></article></div></section><section class="panel pl-scenario-panel"><span class="pl-kicker">DIAGNÓSTICO DA GESTÃO</span><h2>Risco, percurso e robustez</h2><div class="pl-diagnostics"><div><span>Entradas ativas</span><b>${['entryConventional','entryDirect','entryAbsorption'].filter(k=>profile[k]).length}</b></div><div><span>Resultado médio final</span><b>${currency(mc?.averagePayoutTotal)}</b></div><div><span>Faixa temporal</span><b>${mc?.durationP10!=null?`${mc.durationP10}–${mc.durationP90} dias (P10–P90)`:'Execute a simulação'}</b></div><div><span>Modelo de risco</span><b>Gestão de saque</b></div><div><span>Primeiro saque</span><b>${percent(mc?.payoutProbability)}</b></div><div><span>Dois ou mais saques</span><b>${percent(mc?.twoPayoutProbability)}</b></div><div><span>Média de saques</span><b>${number(mc?.averagePayoutCount)}</b></div><div><span>Base</span><b>${trades.length} trades · ${summary?.byDay?.length||0} dias</b></div></div><p class="pl-field-hint">A curva aplica o limite de drawdown e o valor de saque informados. Confira as regras oficiais antes de considerar qualquer valor elegível.</p></section></main></div><div class="info-strip"><span>ⓘ</span><p>Esta simulação estima cenários de deslocamento de DD e saques a partir do histórico. Não é solicitação real de saque nem garantia de elegibilidade.</p></div>`;}

function render(state){const set=activeSet(state);return `<div class="performance-lab ${state.activeTab==='geral'?'':'compact-sim'}"><section class="pl-hero"><div class="pl-hero-copy"><span class="eyebrow">HUNTER · PERFORMANCE LAB</span><h2>Desempenho com contexto.<br><em>Decisões com clareza.</em></h2><p>Analise o histórico de operações e simule regras configuráveis de avaliação e saque.</p></div><div class="pl-hero-side"><span class="pl-hero-label">CONJUNTO ATIVO</span>${set?`<strong>${esc(set.name)}</strong><small>${set.trades?.length||0} operações ${set.summaries?.length?`· ${set.summaries.length} resumo(s)`:''}</small>`:`<strong>Nenhum arquivo importado</strong><small>Comece com relatório NinjaTrader ou CSV Grid</small>`}<button class="button primary" data-pl="toggle-import">＋ Importar dados</button></div></section><div class="pl-context"><label>Conjunto<select data-pl-select="dataset"><option value="">Selecione uma análise</option>${state.datasets.map(item=>`<option value="${esc(item.id)}" ${item.id===state.activeDatasetId?'selected':''}>${esc(item.name)}</option>`).join('')}</select></label>${set?`<span>Período ${esc(set.startDate||'—')} – ${esc(set.endDate||'—')} · origem ${set.sources?.map(esc).join(', ')||'CSV NinjaTrader'}</span><button type="button" class="text-button" data-pl="remove-dataset">Remover conjunto</button>`:`<span>Seus arquivos continuam separados das análises HSG e das contas de trader.</span>`}</div><nav class="pl-tabs" aria-label="Abas do Performance Lab">${[['geral','Geral'],['aprovacao','Aprovação'],['saque','Saque']].map(([id,label])=>`<button type="button" data-pl-tab="${id}" aria-current="${state.activeTab===id?'page':'false'}">${label}</button>`).join('')}</nav>${importPanel(state)}<div class="pl-content">${state.activeTab==='geral'?renderGeneral(set):state.activeTab==='aprovacao'?renderEvaluation(set,state):renderWithdrawal(set,state)}</div></div>`;}

export function renderPerformanceLab(view,state,persist){
  const draw=()=>{view.innerHTML=render(state);const root=view.querySelector('.performance-lab'),set=activeSet(state);if(root)root.insertAdjacentHTML('afterbegin',labTopbar(state,set));root?.querySelector('.pl-hero')?.remove();root?.querySelector('.pl-context')?.remove();root?.querySelector(':scope > .pl-tabs')?.remove();const importPanelNode=root?.querySelector('.pl-import');if(importPanelNode){importPanelNode.classList.toggle('open',state.showImport);importPanelNode.hidden=!state.showImport;}root?.insertAdjacentHTML('beforeend','<footer class="pl-lab-footer"><span>Hunter Performance Lab</span><span>Estimativas não garantem aprovação ou saque.</span></footer>');bind();};
  const save=()=>{persist(state);draw();};
  const bind=()=>{
    view.querySelectorAll('[data-pl-tab]').forEach(button=>button.onclick=()=>{state.activeTab=button.dataset.plTab;save();});
    view.querySelectorAll('[data-pl="toggle-import"]').forEach(button=>button.addEventListener('click',()=>{state.showImport=!state.showImport;pendingImport=null;draw();if(state.showImport)view.querySelector('[data-pl-form="import"] [name="files"]')?.click();}));
    view.querySelector('[data-pl="exit-lab"]')?.addEventListener('click',()=>document.querySelector('[data-page="hsg"]')?.click());
    view.querySelector('[data-pl="logout"]')?.addEventListener('click',()=>document.querySelector('#logout')?.click());
    view.querySelectorAll('[data-pl-filter]').forEach(input=>input.addEventListener('change',()=>{state.entryFilters={...state.entryFilters,[input.dataset.plFilter]:input.checked};save();}));
    view.querySelector('[data-pl="export"]')?.addEventListener('click',()=>{const current=activeSet(state);if(!current)return;const rows=[['Date','Time','Profit','Side','Symbol','EntryMode'],...(current.trades||[]).map(t=>[t.date,t.time||'',t.profit,t.side||'',t.symbol||'',t.entryMode||''])];const csv=rows.map(row=>row.map(cell=>`"${String(cell??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=`hunter-performance-${new Date().toISOString().slice(0,10)}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
    view.querySelectorAll('[data-pl-account]').forEach(button=>button.addEventListener('click',()=>{const form=button.closest('form'),input=form?.elements.namedItem('startingBalance');if(!input)return;input.value=button.dataset.plAccount;form.querySelectorAll('[data-pl-account]').forEach(item=>item.classList.toggle('selected',item===button));}));
    view.querySelector('[data-pl="reset-profile"]')?.addEventListener('click',event=>{const form=event.currentTarget.closest('form');if(form?.dataset.plForm==='evaluation')state.evaluationProfile={...emptyProfile};else state.withdrawalProfile={...emptyProfile};save();});
    view.querySelector('[data-pl="suggest-management"]')?.addEventListener('click',event=>{const form=event.currentTarget.closest('form'),kind=form?.dataset.plForm,set=activeSet(state),profile=kind==='evaluation'?state.evaluationProfile:state.withdrawalProfile;if(!form||!set?.trades?.length||!set.sequenceReliable){window.alert('Importe um CSV Grid em ordem confiável antes de buscar uma gestão.');return;}let best=null;if(kind==='evaluation'){const maxDD=Number(profile.maxDrawdown)||4500;for(const ratio of [.12,.16,.2,.24,.28])for(const maxStops of [1,2,3,4]){const candidate={...profile,stopDaily:Math.round(maxDD*ratio),dailyLossLimit:Math.round(maxDD*ratio),guard_dailyStop:true,guard_maxStops:true,maxStops,guard_maxTrades:true,maxTrades:6,guard_dailyTarget:true,dailyTarget:Number(profile.dailyTarget)||1200};const result=simulateEvaluationScenarios(set.trades,candidate,true,120),score=result.horizons?.at(-1)?.approvalPct-(result.horizons?.at(-1)?.violationPct||0)*1.5;if(Number.isFinite(score)&&(!best||score>best.score))best={score,profile:candidate};}}else{for(const amount of [500,750,1000,1250])for(const margin of [0,250,500]){const candidate={...profile,withdrawalAmount:amount,prePayoutMargin:margin};const result=simulateWithdrawalScenarios(set.trades,candidate,true,120),score=(result.payoutProbability||0)-(result.violationProbability||0)*1.5;if(Number.isFinite(score)&&(!best||score>best.score))best={score,profile:candidate};}}if(!best){window.alert('Não foi possível comparar gestões com os parâmetros atuais.');return;}if(kind==='evaluation')state.evaluationProfile={...state.evaluationProfile,...best.profile,optimized:true};else state.withdrawalProfile={...state.withdrawalProfile,...best.profile,optimized:true};state.audit.unshift({action:'optimize-management',kind,score:best.score,at:new Date().toISOString()});save();});
    view.querySelectorAll('.pl-guard-card input[type="checkbox"]').forEach(input=>input.addEventListener('change',()=>{const label=input.closest('.pl-guard-card')?.querySelector('span');if(label)label.lastChild.textContent=input.checked?' CONSIDERADO':' IGNORADO';}));
    view.querySelector('[data-pl-select="dataset"]')?.addEventListener('change',event=>{state.activeDatasetId=event.target.value;save();});
    view.querySelector('[data-pl="cancel-import"]')?.addEventListener('click',()=>{pendingImport=null;draw();});
    view.querySelector('[data-pl="remove-dataset"]')?.addEventListener('click',()=>{const dataset=state.datasets.find(item=>item.id===state.activeDatasetId);if(!dataset)return;const files=(dataset.sources||[]).join(', ')||'sem arquivos identificados';if(!confirm(`Excluir o conjunto “${dataset.name}” e seus dados importados?\n\nArquivos: ${files}\nTrades: ${dataset.trades?.length||0} · resumos: ${dataset.summaries?.length||0}\n\nEssa exclusão não pode ser desfeita.`))return;state.datasets=state.datasets.filter(item=>item.id!==dataset.id);state.activeDatasetId=state.datasets[0]?.id||'';state.audit.unshift({action:'remove-dataset',datasetId:dataset.id,datasetName:dataset.name,sources:[...(dataset.sources||[])],trades:dataset.trades?.length||0,summaries:dataset.summaries?.length||0,at:new Date().toISOString()});save();});
    view.querySelector('[data-pl-form="evaluation"]')?.addEventListener('submit',event=>{event.preventDefault();const data=formValues(event.currentTarget);state.evaluationProfile={...state.evaluationProfile,...data,dailyLossLimit:data.guard_dailyStop?(data.stopDaily||data.dailyLossLimit):'0'};state.audit.unshift({action:'update-evaluation-profile',at:new Date().toISOString()});save();});
    view.querySelector('[data-pl-form="withdrawal"]')?.addEventListener('submit',event=>{event.preventDefault();const data=formValues(event.currentTarget);state.withdrawalProfile={...state.withdrawalProfile,...data};state.audit.unshift({action:'update-withdrawal-profile',at:new Date().toISOString()});save();});
    view.querySelector('[data-pl-form="import"] [name="files"]')?.addEventListener('change',event=>{if(event.target.files?.length)event.target.form?.requestSubmit();});
    view.querySelector('[data-pl-form="import"]')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,files=[...form.elements.files.files],error=form.querySelector('.form-errors');if(!files.length){error.textContent='Selecione ao menos um arquivo CSV.';return;}const parsed=await Promise.all(files.map(async file=>parsePerformanceCsv(await file.text(),file.name)));const preview=previewPerformanceImports(state.datasets,parsed);if(!parsed.some(item=>item.kind==='summary'||item.kind==='grid'&&item.records.length>0)){error.textContent=importFailureMessage(parsed,preview);return;}pendingImport={preview,name:files.length===1?files[0].name.replace(/\.csv$/i,''):`Análise ${new Date().toLocaleDateString('pt-BR')}`};draw();});
    view.querySelector('[data-pl="confirm-import"]')?.addEventListener('click',()=>{if(!pendingImport)return;const preview=pendingImport.preview;const form=view.querySelector('.pl-preview');const name=form.querySelector('[name="dataset-name"]').value.trim();if(!name){form.querySelector('[name="dataset-name"]').focus();return;}const includeDuplicates=form.querySelector('[name="include-duplicates"]').checked;const trades=preview.records.filter(trade=>includeDuplicates||!preview.duplicateIds.has(trade.id));if(!trades.length&&!preview.summaries.length){form.querySelector('[name="dataset-name"]').focus();return;}const dates=trades.map(t=>t.date).sort();const id=crypto.randomUUID();const set={id,name,trades,summaries:preview.summaries,sequenceReliable:preview.sequenceReliable,duplicateCount:preview.duplicates,overlaps:preview.overlaps,sources:preview.sources||[...new Set([...preview.records.map(t=>t.sourceFile),...preview.summaries.map(s=>s.filename)])],startDate:dates[0]||'',endDate:dates.at(-1)||'',importedAt:new Date().toISOString()};state.datasets.push(set);state.activeDatasetId=id;state.audit.unshift({action:'import',datasetId:id,trades:trades.length,summaries:set.summaries.length,duplicates:preview.duplicates,at:set.importedAt});pendingImport=null;state.showImport=false;save();});
  };
  draw();
}
